def test_node_password_compatibility():
    # Fixed result generated by Node scryptSync('Migration-password!', salt, 64).
    import subprocess
    result = subprocess.run(['node','-e',"process.stdout.write(require('node:crypto').scryptSync('Migration-password!','0123456789abcdef0123456789abcdef',64).toString('hex'))"],capture_output=True,text=True,check=True)
    stored = '0123456789abcdef0123456789abcdef:'+result.stdout
    assert verify_password('Migration-password!',stored)
    assert not verify_password('wrong',stored)
    assert not verify_password('wrong','malformed')


def test_transaction_rolls_back_customer_order_stock_and_events(store,product):
    data = {'name':'Synthetic','email':'synthetic@example.test','phone':'local-phone','address':'Address','items':[{'slug':product['id'],'qty':1}],'whatsappConsent':True}
    with pytest.raises(ApiError): business.create_order(data,'website')
    assert record('products',product['id'])['stock']==10
    assert not records('customers') and not records('orders')
    assert not one('SELECT * FROM auto_events')


def test_schema_migration_preserves_existing_rows(store):
    row = one('SELECT * FROM users WHERE id=?','admin')
    initialize(store)
    assert one('SELECT * FROM users WHERE id=?','admin')==row
    assert one('PRAGMA integrity_check')['integrity_check']=='ok'
    assert not all_rows('PRAGMA foreign_key_check')
    assert one('SELECT count(*) AS n FROM auto_workflows')['n']==4


