@pytest.mark.parametrize('material,variant,rate,weight,making,stone,expected',[
    ('gold','24K',10000,1,10,None,11330),
    ('gold','22K',9200,1,10,None,10423.6),
    ('gold','14K',7500,1,0,None,7500*14/18*1.03),
    ('silver','925',100000,10,10,None,1048.025),
    ('diamond','18K',7500,1,10,1000,9527.5),
])
def test_rate_based_pricing(store,material,variant,rate,weight,making,stone,expected):
    save('settings','rates',{'gold24':rate,'gold22':rate,'gold18':rate,'silver999':rate})
    product={'material':material,'price':None,'weightGrams':weight,'makingChargePct':making,'stoneValue':stone}
    assert business.price_total(product,variant)==pytest.approx(expected)


def test_unknown_pricing_inputs_remain_unpurchasable(store):
    p={'material':'diamond','price':None,'weightGrams':1,'makingChargePct':10,'stoneValue':None}
    assert business.price_total(p,'18K') is None
    save('settings','rates',{'gold18':7500})
    assert business.price_total(p,'18K') is None
    assert business.price_total({**p,'price':5000},'18K')==5000
